package vn.edu.eaut.lab6.controller; import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import vn.edu.eaut.lab6.store.StudentStore;@WebServlet("/student-delete") public class DeleteStudentServlet extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{StudentStore.delete(q.getParameter("id"));p.sendRedirect(q.getContextPath()+"/students");}}
